import{_ as i,o as e,c as t,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2020-04-21 :: Ceph Crimson Meeting","description":"","frontmatter":{"title":"2020-04-21 :: Ceph Crimson Meeting","date":"2020-04-21T00:00:00.000Z","updated":"2020-04-30T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可伸缩性","对象存储","块存储","文件系统存储","一致性","去中心化","性能","Bluestore","Bluefs","Rocksdb","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","身份验证","授权","加密","损坏码","复制","快照","克隆","虚拟化","云计算","存储","节点","磁盘","SSD","HDD","JBOD","SAN","NAS","网络","网络拓扑","故障域","恢复","弹性","负载均衡","缓存","压缩","去重","等级存储","性能调整","基准测试","测试","验证"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-04-21_-_-_Ceph_Crimson_Meeting.md","filePath":"posts/2020/2020-04-21_-_-_Ceph_Crimson_Meeting.md","lastUpdated":1780460162000}'),o={name:"posts/2020/2020-04-21_-_-_Ceph_Crimson_Meeting.md"};function r(s,l,n,_,h,p){return e(),t("div",null,[...l[0]||(l[0]=[a('<p>在2020年4月21日的Ceph Crimson会议中，参与者讨论了Ceph分布式存储系统的多个技术问题。以下是对会议内容的总结：</p><h3 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h3><ul><li><strong>日期</strong>: 2020年4月21日</li><li><strong>参与者</strong>: 未列出具体人员</li><li><strong>议程</strong>: 讨论了Ceph存储系统的技术问题，包括节点大小调整、数据结构设计、代码实现和测试等。</li></ul><h3 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h3><ol><li><p><strong>节点大小调整问题</strong>:</p><ul><li>讨论了在Ceph中调整节点大小的可行性和效率问题。</li><li>决定简化处理，不考虑双分裂情况，但节点一旦存储在树中，其大小不可更改。</li><li>提出了通过写入新的大块来处理节点大小扩展的方法。</li></ul></li><li><p><strong>数据结构设计</strong>:</p><ul><li>讨论了O节点（Onoda notes）的内部结构设计，包括固定大小和可变大小部分的分离。</li><li>提出了将O节点分为固定大小和可变大小两部分的设计思路。</li></ul></li><li><p><strong>代码实现和测试</strong>:</p><ul><li>讨论了代码实现的进展，包括已经实现的专利函数和即将进行的提取重设计。</li><li>提到了正在进行单元测试的开发，包括FS和LBA树的插入和分裂操作。</li><li>强调了文档编写和代码提交的重要性。</li></ul></li><li><p><strong>其他技术问题</strong>:</p><ul><li>讨论了日志恢复、树节点类设计、块布局和哈希碰撞处理等问题。</li><li>提出了优先考虑空间效率而非计算效率的设计原则。</li></ul></li></ol><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li>简化节点大小调整的处理逻辑。</li><li>设计O节点的内部结构，分为固定大小和可变大小两部分。</li><li>继续推进代码实现和单元测试的开发。</li><li>编写相关文档并提交代码审查。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>完成单元测试的开发，并编写相关文档。</li><li>提交代码审查，并根据反馈进行调整。</li><li>继续进行提取重设计和日志恢复的开发。</li><li>关注并处理网络和会议时间安排的问题。</li></ul><h3 id="其他备注" tabindex="-1">其他备注 <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注&quot;">​</a></h3><ul><li>会议中提到了网络问题和会议时间安排的调整，需要进一步确认和处理。</li><li>会议记录和讨论内容将更新到共享文档中，供后续参考。</li></ul>',11)])])}const c=i(o,[["render",r]]);export{u as __pageData,c as default};
